<?php
declare(strict_types=1);
require_once __DIR__.'/includes/ui.php';require_once __DIR__.'/includes/economy.php';
if(pv_is_logged_in())pv_redirect('dashboard.php');
$starters=['agumon','gabumon','tentomon','veemon','guilmon','terriermon'];$error='';$db=null;
try{$db=pv_db();if(!pv_table_exists('digimon_species'))$db=null;}catch(Throwable){}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'&&$db){
    try{
        pv_require_csrf();$username=trim((string)($_POST['username']??''));$email=trim((string)($_POST['email']??''));$pw=(string)($_POST['password']??'');$pw2=(string)($_POST['password2']??'');$starter=(string)($_POST['starter']??'agumon');$tamer=nxt_skin_id((int)($_POST['tamer']??102));
        if(!preg_match('/^[A-Za-z0-9_]{3,24}$/',$username))throw new RuntimeException('Username must be 3–24 characters using letters, numbers or underscores.');
        if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid email address.');
        if(strlen($pw)<8)throw new RuntimeException('Password must contain at least 8 characters.');if($pw!==$pw2)throw new RuntimeException('Passwords do not match.');if(!in_array($starter,$starters,true))throw new RuntimeException('Choose a valid starter.');
        $species=dn_species_by_slug($db,$starter);if(!$species)throw new RuntimeException('Starter catalog is unavailable.');
        $db->begin_transaction();$hash=pv_password_hash($pw);$now=time();$date=date('Y-m-d H:i:s');$ip=substr((string)($_SERVER['REMOTE_ADDR']??''),0,64);
        $stmt=$db->prepare('INSERT INTO members(username,password,email,registered,llogin,last_login,ip,created_avatar) VALUES(?,?,?,?,?,?,?,?)');if(!$stmt)throw new RuntimeException('Account creation is unavailable.');$stmt->bind_param('sssiissi',$username,$hash,$email,$now,$now,$date,$ip,$tamer);if(!$stmt->execute()){if($stmt->errno===1062)throw new RuntimeException('That username or email is already registered.');throw new RuntimeException($stmt->error);}$uid=(int)$db->insert_id;$stmt->close();
        $show=1;$stmt=$db->prepare('INSERT INTO members_options(id,tamer,memonmap) VALUES(?,?,?)');if(!$stmt)throw new RuntimeException('Could not create tamer options.');$stmt->bind_param('iii',$uid,$tamer,$show);if(!$stmt->execute())throw new RuntimeException($stmt->error);$stmt->close();
        $instance=dn_create_instance($db,$uid,(int)$species['id'],'starter',5);$slot=1;$stmt=$db->prepare('INSERT INTO digimon_party(owner_id,slot,digimon_id) VALUES(?,?,?)');if(!$stmt)throw new RuntimeException('Could not initialize starter party slot.');$stmt->bind_param('iii',$uid,$slot,$instance);if(!$stmt->execute())throw new RuntimeException($stmt->error);$stmt->close();$squadSlot=2;foreach(['terriermon','tentomon','gabumon'] as $supportSlug){if($supportSlug===$starter)continue;$support=dn_species_by_slug($db,$supportSlug);if(!$support)continue;$supportId=dn_create_instance($db,$uid,(int)$support['id'],'starter',5);dn_write($db,'INSERT INTO digimon_party(owner_id,slot,digimon_id) VALUES(?,?,?)',[$uid,$squadSlot,$supportId]);if(++$squadSlot>3)break;}$starterItems=['hp-capsule-s'=>5,'sp-capsule-s'=>5];foreach($starterItems as $slug=>$qty){$stmt=$db->prepare('SELECT id FROM items WHERE slug=? LIMIT 1');$stmt->bind_param('s',$slug);$stmt->execute();$it=$stmt->get_result()->fetch_assoc();$stmt->close();if($it)dn_add_item($db,$uid,(int)$it['id'],$qty);}$db->commit();
        session_regenerate_id(true);$_SESSION['myid']=$uid;$_SESSION['myuser']=$username;$_SESSION['session_version']=0;dn_world_identity($uid,$username);dn_world_event('auth','account.created','New tamer account created with a starter party');$_SESSION['map_preferences']=[0,1,$tamer];$_SESSION['world_key']='cyberspace';$_SESSION['world_area']='dawn-001';$_SESSION['csrf_token']=bin2hex(random_bytes(32));pv_redirect('dashboard.php?welcome=1');
    }catch(Throwable $e){try{$db->rollback();}catch(Throwable){};$error=$e->getMessage();}
}
pv_page_start('Create Tamer','signup.php',false);
