<main class="nxt-document nxt-signup"><section class="pv-card nxt-document-panel"><div class="nxt-document-head"><div><span class="pv-eyebrow">DIGIMON NXT / NEW CONNECTION</span><h1>Your next adventure starts here.</h1></div><?=nxt_sprite('agumon')?></div><p class="pv-subtle">Choose a starter Digimon and a playable tamer skin. Start with your chosen level 5 partner and two companion Digimon, ready for three-versus-three battles.</p><?php if($error):?><div class="pv-flash error"><?=pv_h($error)?></div><?php endif;?><?php if(!$db):?><div class="pv-flash error">Database setup is required before accounts can be created. <a href="<?=pv_h(pv_url('_setup.php'))?>">Open setup</a>.</div><?php else:?><form method="post"><?=pv_csrf_field()?><div class="pv-grid cols-2"><div class="pv-field"><label>Username</label><input name="username" maxlength="24" value="<?=pv_h((string)($_POST['username']??''))?>" required></div><div class="pv-field"><label>Email</label><input type="email" name="email" maxlength="160" value="<?=pv_h((string)($_POST['email']??''))?>" required></div><div class="pv-field"><label>Password</label><input type="password" name="password" minlength="8" required></div><div class="pv-field"><label>Confirm password</label><input type="password" name="password2" minlength="8" required></div></div><h3>Playable tamer skin</h3><?php nxt_skin_picker((int)($_POST['tamer']??102));?><h3 style="margin-top:18px">Starter Digimon</h3><div class="dn-scan-grid"><?php foreach($starters as $slug):$s=dn_species_by_slug($db,$slug);if(!$s)continue;?><label class="dn-scan-card" style="cursor:pointer"><input type="radio" name="starter" value="<?=pv_h($slug)?>" <?=((string)($_POST['starter']??'agumon')===$slug)?'checked':''?>><img src="<?=pv_h(pv_static((string)$s['sprite']))?>" alt=""><small><?=pv_h((string)$s['stage'])?> // <?=pv_h((string)$s['attribute'])?></small><h3><?=pv_h((string)$s['name'])?></h3></label><?php endforeach;?></div><button class="pv-button" type="submit" style="margin-top:18px">Create Tamer + Enter NXT</button></form><?php endif;?></section></main>
